import React, { Component } from 'react';
import axios from 'axios';
import './KitchenComponent.css';

class KitchenComponent extends Component {
  constructor(props) {
    super(props);
    this.state = {
      pendingTickets: [],
      completedItems: [],
      stats: {
        pendingCount: 0,
        cookingCount: 0,
        todayDoneCount: 48,
        avgTime: '12 Phút'
      }
    };
  }

  componentDidMount() {
    this.fetchKitchenData();
    // Tự động làm mới dữ liệu bếp mỗi 4 giây
    this.timerID = setInterval(() => this.fetchKitchenData(), 4000);
  }

  componentWillUnmount() {
    clearInterval(this.timerID);
  }

  fetchKitchenData = () => {
    const token = localStorage.getItem('token');
    axios.get('/api/admin/orders', {
      headers: { 'x-access-token': token }
    })
    .then((res) => {
      if (Array.isArray(res.data)) {
        // Lọc các đơn hàng đang chờ hoặc đang chế biến (PENDING / APPROVED)
        const activeOrders = res.data.filter(o => o.status === 'PENDING' || o.status === 'APPROVED');
        
        // Mô phỏng ánh xạ dữ liệu đơn hàng thành các phiếu bếp (KDS Tickets)
        const pendingTickets = activeOrders.map((order, index) => ({
          id: order._id,
          tableName: order.table || `Bàn 0${(index % 6) + 1}`,
          timeAgo: `${Math.floor(Math.random() * 15) + 2} phút trước`,
          urgency: index % 2 === 0 ? 'urgent' : 'normal',
          items: order.items ? order.items.map(i => ({
            name: i.product?.name || 'Món ăn',
            quantity: i.quantity || 1,
            note: i.note || ''
          })) : [{ name: 'Phở Bò Đặc Biệt', quantity: 2, note: 'Ít bánh' }]
        }));

        // Dữ liệu món vừa ra bếp (mô phỏng từ đơn hàng hoàn thành gần đây)
        const completedItems = [
          { id: 1, name: 'Bàn 02 - Cơm Tấm Sườn', detail: 'Số lượng: x2 • Xong lúc 19:15' },
          { id: 2, name: 'Bàn 05 - Lẩu Hải Sản', detail: 'Số lượng: x1 • Xong lúc 19:10' },
          { id: 3, name: 'Bàn 06 - Gỏi Cuốn', detail: 'Số lượng: x3 • Xong lúc 19:02' }
        ];

        this.setState({
          pendingTickets,
          completedItems,
          stats: {
            pendingCount: pendingTickets.length,
            cookingCount: pendingTickets.reduce((acc, t) => acc + t.items.length, 0),
            todayDoneCount: 48,
            avgTime: '12 Phút'
          }
        });
      }
    })
    .catch(err => console.error("Lỗi tải dữ liệu bếp:", err));
  }

  // Hàm hoàn thành phiếu bếp chuyển sang phục vụ
  handleCompleteTicket = (ticketId) => {
    const token = localStorage.getItem('token');
    axios.put(`/api/admin/orders/status/${ticketId}`, { status: 'COMPLETED' }, {
      headers: { 'x-access-token': token }
    })
    .then(() => {
      alert('Đã hoàn thành món và chuyển phục vụ!');
      this.fetchKitchenData();
    })
    .catch(err => {
      // Fallback giả lập giao diện nếu chưa có API update status riêng
      const updatedTickets = this.state.pendingTickets.filter(t => t.id !== ticketId);
      this.setState({ pendingTickets: updatedTickets });
    });
  }

  render() {
    const { pendingTickets, completedItems, stats } = this.state;

    return (
      <div className="kitchen-container">
        <div className="kitchen-title">MÀN HÌNH ĐIỀU HÀNH BẾP (KITCHEN DISPLAY)</div>

        {/* 4 Thẻ thống kê tổng quan */}
        <div className="kitchen-stats">
          <div className="k-stat-card">
            <div className="k-stat-label">Phiếu chế biến chờ</div>
            <div className="k-stat-value highlight">{stats.pendingCount} Phiếu</div>
          </div>
          <div className="k-stat-card">
            <div className="k-stat-label">Món đang chế biến</div>
            <div className="k-stat-value">{stats.cookingCount} Món</div>
          </div>
          <div className="k-stat-card">
            <div className="k-stat-label">Đã xong trong ngày</div>
            <div className="k-stat-value">{stats.todayDoneCount} Món</div>
          </div>
          <div className="k-stat-card">
            <div className="k-stat-label">Thời gian trung bình</div>
            <div className="k-stat-value">{stats.avgTime}</div>
          </div>
        </div>

        {/* Khu vực chính chia 2 cột */}
        <div className="kitchen-content">
          {/* Cột trái: Phiếu gọi món đang chờ chế biến */}
          <div className="cooking-queue-section">
            <div className="section-header">
              <span>Phiếu Gọi Món Đang Chờ Chế Biến</span>
              <span className="sub-note">Ưu tiên theo thời gian gọi</span>
            </div>

            <div className="ticket-grid">
              {pendingTickets.length > 0 ? pendingTickets.map((ticket) => (
                <div key={ticket.id} className="ticket-card">
                  <div>
                    <div className="ticket-header">
                      <span className="table-title">{ticket.tableName}</span>
                      <span className={`time-badge ${ticket.urgency}`}>{ticket.timeAgo}</span>
                    </div>

                    <div className="item-list">
                      {ticket.items.map((item, idx) => (
                        <div key={idx} className="order-item-row">
                          <span><b>x{item.quantity}</b> {item.name}</span>
                          {item.note && <span className="item-note">{item.note}</span>}
                        </div>
                      ))}
                    </div>
                  </div>

                  <button 
                    className="btn-complete"
                    onClick={() => this.handleCompleteTicket(ticket.id)}
                  >
                    Hoàn thành & Chuyển Phục Vụ
                  </button>
                </div>
              )) : <div className="no-data">Hiện không có phiếu gọi món nào đang chờ.</div>}
            </div>
          </div>

          {/* Cột phải: Món vừa ra bếp */}
          <div className="completed-history-section">
            <div className="section-header">
              <span>Món Vừa Ra Bếp</span>
            </div>

            <div className="history-list">
              {completedItems.map((item) => (
                <div key={item.id} className="history-card">
                  <div className="history-info">
                    <div className="item-name">{item.name}</div>
                    <div className="item-detail">{item.detail}</div>
                  </div>
                  <span className="status-badge-done">Đã Ra Bàn</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default KitchenComponent;
